import torch
import triton, triton.language as tl

torch.cuda.set_device(0)
x = torch.rand(16, 64, 256, 256, device='cuda')
M = 64*256*256; rows = 16
w = torch.ones(M, device='cuda'); b = torch.zeros(M, device='cuda')
ref = torch.nn.functional.layer_norm(x, (64,256,256), w.view(64,256,256), b.view(64,256,256), 1e-5)

def clear_l2():
    d = torch.empty((32,1024,1024), dtype=torch.int64, device='cuda'); d.fill_(42); del d

def time_fn(fn, trials=20):
    for _ in range(3): fn(); torch.cuda.synchronize()
    ts=[]
    for _ in range(trials):
        torch.cuda.synchronize()
        s=torch.cuda.Event(enable_timing=True); e=torch.cuda.Event(enable_timing=True)
        clear_l2(); s.record(); fn(); e.record(); torch.cuda.synchronize()
        ts.append(s.elapsed_time(e))
    return sum(ts)/len(ts), min(ts)

@triton.jit
def red2(X, P, M, CHUNK, BLOCK: tl.constexpr, EV: tl.constexpr):
    row = tl.program_id(0); chunk = tl.program_id(1)
    base = row*M + chunk*CHUNK
    acc = tl.zeros([BLOCK], tl.float32); acc2 = tl.zeros([BLOCK], tl.float32)
    for off in range(0, CHUNK, BLOCK):
        idx = off + tl.arange(0, BLOCK)
        if EV:
            xx = tl.load(X + base + idx, eviction_policy='evict_first')
        else:
            xx = tl.load(X + base + idx)
        acc += xx; acc2 += xx*xx
    S = tl.num_programs(1)
    tl.store(P + row*2*S + chunk, tl.sum(acc))
    tl.store(P + row*2*S + S + chunk, tl.sum(acc2))

@triton.jit
def nrm2(X, W, B, P, Y, M, CHUNK, eps, S: tl.constexpr, BLOCK: tl.constexpr, EV: tl.constexpr):
    row = tl.program_id(0); chunk = tl.program_id(1)
    offs = tl.arange(0, S)
    s = tl.sum(tl.load(P + row*2*S + offs)); s2 = tl.sum(tl.load(P + row*2*S + S + offs))
    mean = s/M; var = s2/M - mean*mean; rstd = 1.0/tl.sqrt(var+eps)
    bx = row*M + chunk*CHUNK; bw = chunk*CHUNK
    for off in range(0, CHUNK, BLOCK):
        idx = off + tl.arange(0, BLOCK)
        if EV:
            xx = tl.load(X + bx + idx, eviction_policy='evict_first')
            ww = tl.load(W + bw + idx)
            bb = tl.load(B + bw + idx)
            tl.store(Y + bx + idx, (xx-mean)*rstd*ww+bb, eviction_policy='evict_first')
        else:
            xx = tl.load(X + bx + idx); ww = tl.load(W + bw + idx); bb = tl.load(B + bw + idx)
            tl.store(Y + bx + idx, (xx-mean)*rstd*ww+bb)

for chunk, block, nw in [(16384, 8192, 16), (16384, 4096, 8), (8192, 4096, 16), (8192, 2048, 8), (4096, 2048, 8), (4096, 4096, 16)]:
