#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>
namespace cg = cooperative_groups;

#ifndef DEV_LIMIT
#define DEV_LIMIT 16
#endif

__global__ void __launch_bounds__(1024, 1) ln_coop_kernel(
    const float4* __restrict__ x4,
    const float4* __restrict__ w4,
    const float4* __restrict__ b4,
    float4* __restrict__ y4,
    float* __restrict__ partials,
    int M4, int rows, float eps)
{
    cg::grid_group grid = cg::this_grid();
    int S = gridDim.x / rows;
    int row = blockIdx.x / S;
    int slice = blockIdx.x % S;
    int per = M4 / S;
    const float4* xr = x4 + (long)row * M4 + (long)slice * per;
    float s = 0.f, s2 = 0.f;
    for (int i = threadIdx.x; i < per; i += blockDim.x) {
        float4 v = xr[i];
        s += v.x + v.y + v.z + v.w;
        s2 += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
    }
    __shared__ float sh[32], sh2[32];
    for (int o = 16; o > 0; o >>= 1) {
        s += __shfl_down_sync(0xffffffffu, s, o);
        s2 += __shfl_down_sync(0xffffffffu, s2, o);
    }
    if ((threadIdx.x & 31) == 0) { sh[threadIdx.x >> 5] = s; sh2[threadIdx.x >> 5] = s2; }
    __syncthreads();
    if (threadIdx.x < 32) {
        s = (threadIdx.x < (blockDim.x >> 5)) ? sh[threadIdx.x] : 0.f;
        s2 = (threadIdx.x < (blockDim.x >> 5)) ? sh2[threadIdx.x] : 0.f;
        for (int o = 16; o > 0; o >>= 1) {
            s += __shfl_down_sync(0xffffffffu, s, o);
            s2 += __shfl_down_sync(0xffffffffu, s2, o);
        }
        if (threadIdx.x == 0) {
            partials[blockIdx.x] = s;
            partials[gridDim.x + blockIdx.x] = s2;
        }
    }
    grid.sync();
    if (blockIdx.x < DEV_LIMIT && threadIdx.x < 32) {
        float a = 0.f, a2 = 0.f;
        for (int k = threadIdx.x; k < S; k += 32) {
            a += partials[row * S + k];
            a2 += partials[gridDim.x + row * S + k];
        }
        for (int o = 16; o > 0; o >>= 1) {
            a += __shfl_down_sync(0xffffffffu, a, o);
            a2 += __shfl_down_sync(0xffffffffu, a2, o);
        }
        if (threadIdx.x == 0) {
            float mean = a / (float)(M4 * 4);
            float var = a2 / (float)(M4 * 4) - mean * mean;
            sh[threadIdx.x] = mean;
            sh2[threadIdx.x] = rsqrtf(var + eps);
        }
    }
    if (blockIdx.x >= DEV_LIMIT) { __syncthreads(); }
    cg::this_grid().sync();
    float mean = sh[0], rstd = sh2[0];
    const float4* wr = w4 + (long)slice * per;
    const float4* br = b4 + (long)slice * per;
    float4* yr = y4 + (long)row * M4 + (long)slice * per;
    for (int i = threadIdx.x; i < per; i += blockDim.x) {
        float4 v = xr[i];
        float4 wv = wr[i];
        float4 bv = br[i];
        float4 r;
        r.x = (v.x - mean) * rstd * wv.x + bv.x;
        r.y = (v.y - mean) * rstd * wv.y + bv.y;
        r.z = (v.z - mean) * rstd * wv.z + bv.z;
        r.w = (v.w - mean) * rstd * wv.w + bv.w;
        yr[i] = r;
    }
}

torch::Tensor ln_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b, double eps, int64_t S, int64_t threads) {
    int64_t M = w.numel();
    int64_t rows = x.numel() / M;
    auto y = torch::empty_like(x);
    int grid = (int)(rows * S);
    auto partials = torch::empty({2 * grid}, x.options());
    int M4 = (int)(M / 4);
    const float4* x4 = reinterpret_cast<const float4*>(x.data_ptr<float>());
    const float4* w4 = reinterpret_cast<const float4*>(w.data_ptr<float>());
    const float4* b4 = reinterpret_cast<const float4*>(b.data_ptr<float>());
    float4* y4 = reinterpret_cast<float4*>(y.data_ptr<float>());
    float* p = partials.data_ptr<float>();
    float epsf = (float)eps;
    void* args[] = {(void*)&x4, (void*)&w4, (void*)&b4, (void*)&y4, (void*)&p, (void*)&M4, (void*)&rows, (void*)&epsf};
    int rowsi = (int)rows;
    void* args2[] = {(void*)&x4, (void*)&w4, (void*)&b4, (void*)&y4, (void*)&p, (void*)&M4, (void*)&rowsi, (void*)&epsf};
    cudaError_t err = cudaLaunchCooperativeKernel((void*)ln_coop_kernel, dim3(grid), dim3((int)threads), args2, 0, 0);
    TORCH_CHECK(err == cudaSuccess, "coop launch failed: ", cudaGetErrorString(err));
    return y;
}

int max_grid(int64_t threads) {
    static int dev = -1, numSM = 0, maxB = 0;
    if (dev < 0) {
        cudaGetDevice(&dev);
        cudaDeviceGetAttribute(&numSM, cudaDevAttrMultiProcessorCount, dev);
    }
    int mb = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&mb, (void*)ln_coop_kernel, (int)threads, 0);
    return numSM * mb;
}

int run_check() {
    auto opts = torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA);
    auto x = torch::rand({16, 64, 256, 256}, opts);
    auto w = torch::rand({64, 256, 256}, opts);
    auto b = torch::rand({64, 256, 256}, opts);
    auto ref = torch::nn::functional::layer_norm(x, torch::nn::functional::LayerNormFuncOptions({64, 256, 256}).weight(w).bias(b).eps(1e-5));
    int mb = max_grid(1024);
    printf("max blocks @1024 threads: %d\n", mb);
    auto y = ln_forward(x, w.reshape({-1}), b.reshape({-1}), 1e-5, 128, 1024);
    auto d = (y - ref).abs().max().item<float>();
    printf("max diff coop: %g\n", d);
    return d < 1e-4 ? 0 : 1;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("ln_forward", &ln_forward);
    m.def("max_grid", &max_grid);
    m.def("run_check", &run_check);
}
